BEGIN IMMEDIATE;
CREATE TABLE organizations(id TEXT PRIMARY KEY);
CREATE TABLE tenants(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id));
CREATE TABLE projects(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), UNIQUE(tenant_id,id));
CREATE TABLE agents(uid TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id), UNIQUE(tenant_id,project_id,uid));
CREATE TABLE principals(tenant_id TEXT NOT NULL REFERENCES tenants(id), subject_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('human','service_account','workload')), revocation_epoch INTEGER NOT NULL DEFAULT 0 CHECK(revocation_epoch>=0), PRIMARY KEY(tenant_id,subject_id));
CREATE TABLE role_bindings(tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, agent_uid TEXT NOT NULL, subject_id TEXT NOT NULL, role TEXT NOT NULL, FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid), FOREIGN KEY(tenant_id,subject_id) REFERENCES principals(tenant_id,subject_id), PRIMARY KEY(tenant_id,project_id,agent_uid,subject_id,role));
CREATE TABLE identity_policies(tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, agent_uid TEXT NOT NULL, version TEXT NOT NULL, document_json TEXT NOT NULL, FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid), PRIMARY KEY(tenant_id,project_id,agent_uid,version));
CREATE TABLE identity_policy_heads(tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, agent_uid TEXT NOT NULL, version TEXT NOT NULL, PRIMARY KEY(tenant_id,project_id,agent_uid), FOREIGN KEY(tenant_id,project_id,agent_uid,version) REFERENCES identity_policies(tenant_id,project_id,agent_uid,version));
CREATE TABLE session_scopes(session_id TEXT PRIMARY KEY REFERENCES sessions(id), tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, agent_uid TEXT NOT NULL, FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid));
CREATE TABLE run_authorizations(run_id TEXT PRIMARY KEY REFERENCES runs(id), tenant_id TEXT NOT NULL, project_id TEXT NOT NULL, agent_uid TEXT NOT NULL, subject_id TEXT NOT NULL, revocation_epoch INTEGER NOT NULL, snapshot_json TEXT NOT NULL, digest TEXT NOT NULL, FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid), FOREIGN KEY(tenant_id,subject_id) REFERENCES principals(tenant_id,subject_id));
INSERT INTO organizations VALUES('local-organization');
INSERT INTO tenants VALUES('local-tenant','local-organization');
INSERT INTO projects VALUES('local-project','local-tenant');
INSERT INTO agents VALUES('local-agent','local-tenant','local-project');
INSERT INTO principals VALUES('local-tenant','local-subject','human',0);
INSERT INTO role_bindings VALUES('local-tenant','local-project','local-agent','local-subject','tenant_admin');
INSERT INTO identity_policies VALUES('local-tenant','local-project','local-agent','local-policy-1','{"version":"local-policy-1","hard_denies":[],"conditions":{"tenant_id":null,"project_id":null,"agent_uid":null,"workspace":null,"entry_channels":null,"tool_effects":null,"not_before_ms":null,"expires_at_ms":null,"networks":null}}');
INSERT INTO identity_policy_heads VALUES('local-tenant','local-project','local-agent','local-policy-1');
INSERT INTO session_scopes SELECT id,'local-tenant','local-project','local-agent' FROM sessions;
CREATE TRIGGER local_session_scope AFTER INSERT ON sessions BEGIN INSERT INTO session_scopes VALUES(NEW.id,'local-tenant','local-project','local-agent'); END;
CREATE TRIGGER immutable_run_authorization BEFORE UPDATE ON run_authorizations BEGIN SELECT RAISE(ABORT,'immutable run authorization'); END;
CREATE TRIGGER immutable_policy BEFORE UPDATE ON identity_policies BEGIN SELECT RAISE(ABORT,'immutable policy version'); END;
INSERT INTO schema_migrations VALUES(21,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
